import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Rectangle;
import org.eclipse.swt.widgets.Canvas;

public class Example {
    private static final int INSET = 5;

    public void draw(GC gc, Canvas canvas) {
        Rectangle bounds = canvas.getBounds();
        int yy = 10;
        int hh = 20;
        // Original buggy line: used bounds.x instead of bounds.width
        gc.fillRectangle(INSET, yy, bounds.x - (2 * INSET), hh);
    }
}

afterExample:
import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Rectangle;
import org.eclipse.swt.widgets.Canvas;

public class Example {
    private static final int INSET = 5;

    public void draw(GC gc, Canvas canvas) {
        Rectangle bounds = canvas.getBounds();
        int yy = 10;
        int hh = 20;
        // Corrected line: uses bounds.width
        gc.fillRectangle(INSET, yy, bounds.width - (2 * INSET), hh);
    }
}

