import org.eclipse.swt.graphics.GC;
import org.eclipse.swt.graphics.Rectangle;

public class NegativeExample {
    public void draw(GC gc) {
        Rectangle rect = new Rectangle(10, 20, 100, 50);
        int xOffset = 5;
        // This is a valid usage where rect.x is intended as the x-coordinate, not part of a width calculation with subtraction.
        gc.fillRectangle(rect.x, rect.y, rect.width, rect.height); 

        // This pattern must not match if rect.x is used as a coordinate, not a calculated width.
        gc.fillRectangle(xOffset, 10, 50, 30);

        // Other method call not related to fillRectangle
        int newX = rect.x + 10;
    }
}
